"""Render audit trail. Images are generated by the harness (Claude Code / OpenCode / Codex) with whatever
image tool it exposes; these helpers only order the reference images and log each result.

  reference_images()  the ordered list of images to attach (the prompt says what each one is)
  register()          copy generated images into renders/<shot>/vN-i.<ext> + vN.json (prompt, engine, refs)
"""
from __future__ import annotations

import re
import shutil
from pathlib import Path

from . import paths
from .paths import Product, die


def _next_version(shot_dir: Path) -> int:
    vs = [int(m.group(1)) for f in shot_dir.glob("v*-*.*") if (m := re.match(r"v(\d+)-", f.name))]
    return max(vs, default=0) + 1


def shot_slug(shot: str) -> str:
    return paths.slugify(shot)


def reference_images(prod: Product, *, only_primary=False, no_product_refs=False, extra=None, with_style_refs=False) -> list[Path]:
    """Order: primary subject photo, other subject photos, extra --ref files, then refs/ (style refs).
    A concept job (no subject photo) has only --ref files and refs/."""
    if no_product_refs or not prod.images:
        refs = []
    else:
        refs = [prod.primary_image] if only_primary else list(prod.images)
    refs += [paths.p(r) for r in (extra or [])]
    if with_style_refs:
        refs += prod.style_refs
    for r in refs:
        if not r.exists():
            die(f"reference image not found: {r}")
    return refs


def register(prod: Product, shot: str, images: list[Path], prompt: str, engine: str, refs: list[Path],
             model: str | None = None, params: dict | None = None, notes: str | None = None) -> dict:
    """Log images produced by the harness's image tool into the audit trail (one version, n variations)."""
    for image in images:
        if not image.exists():
            die(f"image not found: {image}")
        if image.suffix.lower() not in paths.IMAGE_EXTS:
            die(f"not an image ({', '.join(sorted(paths.IMAGE_EXTS))}): {image}")
    shot_dir = prod.work / "renders" / shot_slug(shot)
    shot_dir.mkdir(parents=True, exist_ok=True)
    version = _next_version(shot_dir)
    files = []
    for i, image in enumerate(images, 1):
        out = shot_dir / f"v{version}-{i}{image.suffix.lower()}"
        shutil.copy2(image, out)
        files.append(paths.rel(out))
    meta = {
        "product_id": prod.id, "shot": shot, "version": version, "engine": engine, "model": model,
        "params": params or {}, "references": [paths.rel(r) for r in refs], "prompt": prompt,
        "originals": [str(i) for i in images], "files": files, "notes": notes, "created_at": paths.now(),
    }
    paths.write_json(shot_dir / f"v{version}.json", meta)
    paths.record(prod, f"render:{shot_slug(shot)}", version=version, files=len(files), engine=engine)
    return meta


def meta_for(render_path: Path) -> dict | None:
    m = re.match(r"(v\d+)-\d+", render_path.stem)
    if not m:
        return None
    return paths.read_json(render_path.parent / f"{m.group(1)}.json")
